{"version":3,"file":"course.min.js","sources":["../../src/repository/course.js"],"sourcesContent":["// This file is part of Moodle - http://moodle.org/\n//\n// Moodle is free software: you can redistribute it and/or modify\n// it under the terms of the GNU General Public License as published by\n// the Free Software Foundation, either version 3 of the License, or\n// (at your option) any later version.\n//\n// Moodle is distributed in the hope that it will be useful,\n// but WITHOUT ANY WARRANTY; without even the implied warranty of\n// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n// GNU General Public License for more details.\n//\n// You should have received a copy of the GNU General Public License\n// along with Moodle.  If not, see <http://www.gnu.org/licenses/>.\n\n/**\n * Repository helpers for course planning actions.\n *\n * @module     local_coursegen/repository/course\n * @copyright  2025 Wilber Narvaez <https://datacurso.com>\n * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later\n */\n\nimport ajax from 'core/ajax';\n\n/**\n * Send a plan action (ActionIntent) for a planning session.\n *\n * @param {{recordid: number, pendingAction: Object}} payload - pendingAction is the\n *     ActionIntent: {action, target_ids?, parent_section_id?, position?, instruction?}.\n * @return {Promise<Object>} response\n */\nexport async function sendPlanningFeedback({recordid, pendingAction}) {\n    return ajax.call([\n        {\n            methodname: 'local_coursegen_course_planning_feedback',\n            args: {\n                recordid: Number(recordid) || 0,\n                pending_action: pendingAction,\n            },\n        },\n    ])[0];\n}\n\n/**\n * Get the final AI-generated course settings (fullname, shortname, category) for review.\n *\n * @param {number} recordid The planning session record ID.\n * @return {Promise<{fullname: string, shortname: string, category: number, categories: Array}>}\n */\nexport async function getCourseSettings(recordid) {\n    return ajax.call([\n        {\n            methodname: 'local_coursegen_get_course_settings',\n            args: {recordid: Number(recordid) || 0},\n        },\n    ])[0];\n}\n\n/**\n * Create a course from a stored planning session and apply AI-generated content.\n *\n * @param {{\n *     recordid: number,\n *     fullname?: string,\n *     shortname?: string,\n *     category?: number,\n * }} payload - The payload to create the course\n * - recordid: The planning session record ID in local_coursegen_course_sessions\n * - fullname: Optional override for course fullname\n * - shortname: Optional override for course shortname\n * - category: Optional override for course category ID\n * @return {Promise<Object>} response\n */\nexport async function createCourse({recordid, fullname, shortname, category}) {\n    const args = {\n        recordid: Number(recordid) || 0,\n    };\n    if (typeof fullname === 'string' && fullname.trim()) {\n        args.fullname = fullname.trim();\n    }\n    if (typeof shortname === 'string' && shortname.trim()) {\n        args.shortname = shortname.trim();\n    }\n    if (typeof category === 'number' && category > 0) {\n        args.category = category;\n    }\n    return ajax.call([\n        {\n            methodname: \"local_coursegen_create_course\",\n            args,\n        },\n    ])[0];\n}\n"],"names":["recordid","fullname","shortname","category","args","Number","trim","ajax","call","methodname","pendingAction","pending_action"],"mappings":";;;;;;;6GA0EmCA,SAACA,SAADC,SAAWA,SAAXC,UAAqBA,UAArBC,SAAgCA,sBACzDC,KAAO,CACTJ,SAAUK,OAAOL,WAAa,GAEV,iBAAbC,UAAyBA,SAASK,SACzCF,KAAKH,SAAWA,SAASK,QAEJ,iBAAdJ,WAA0BA,UAAUI,SAC3CF,KAAKF,UAAYA,UAAUI,QAEP,iBAAbH,UAAyBA,SAAW,IAC3CC,KAAKD,SAAWA,iBAEbI,cAAKC,KAAK,CACb,CACIC,WAAY,gCACZL,KAAAA,QAEL,8CA1CiCJ,iBAC7BO,cAAKC,KAAK,CACb,CACIC,WAAY,sCACZL,KAAM,CAACJ,SAAUK,OAAOL,WAAa,MAE1C,2DAxBoCA,SAACA,SAADU,cAAWA,2BAC3CH,cAAKC,KAAK,CACb,CACIC,WAAY,2CACZL,KAAM,CACFJ,SAAUK,OAAOL,WAAa,EAC9BW,eAAgBD,kBAGzB"}
